(x, y, t) => {
  const cx = 240, cy = 120;
  let wx = Math.sin(x*0.018+t*0.3)*12 + Math.cos(y*0.013-t*0.22)*8 + Math.sin((x+y)*0.008+t*0.15)*6;
  let wy = Math.cos(y*0.02-t*0.25)*12 + Math.sin(x*0.016+t*0.32)*8 + Math.cos((x-y)*0.009-t*0.18)*6;
  const wx2 = Math.sin(wx*0.05+t*0.4)*4 + Math.cos(wy*0.04-t*0.3)*3;
  const wy2 = Math.cos(wx*0.04-t*0.35)*4 + Math.sin(wy*0.05+t*0.45)*3;
  const sx = x + wx + wx2, sy = y + wy + wy2;
  const src = [
    [160+Math.sin(t*0.5)*110, 80+Math.cos(t*0.35)*55, 0.07, 2.1],
    [320+Math.cos(t*0.45)*110, 160+Math.sin(t*0.6)*55, 0.085, 1.8],
    [240+Math.sin(t*0.28+2)*150, 120+Math.cos(t*0.42+1)*100, 0.055, 2.4],
    [100+Math.cos(t*0.7+1)*90, 190+Math.sin(t*0.55+3)*70, 0.1, 1.6],
    [380+Math.sin(t*0.38+4)*100, 55+Math.cos(t*0.8+2)*75, 0.065, 2.7],
    [240+Math.cos(t*0.32+5)*130, 210+Math.sin(t*0.48)*90, 0.075, 2.0],
    [60+Math.sin(t*0.6+3)*70, 40+Math.cos(t*0.5+4)*50, 0.11, 1.4],
    [420+Math.cos(t*0.33+1)*80, 200+Math.sin(t*0.65+2)*60, 0.06, 2.8]
  ];
  let aS=0, iS=0, cS=0;
  for (const [sX,sY,f,sp] of src) {
    const d = Math.sqrt((sx-sX)**2+(sy-sY)**2);
    const wave = Math.sin(d*f - t*sp);
    const wave2 = Math.sin(d*f*0.618 - t*sp*1.618 + 0.5);
    aS += wave;
    iS += Math.sin(d*f*0.7 + t*sp*0.6 + 1.5) * 0.7 + wave2 * 0.3;
    cS += Math.sin(d*f*1.5 - t*sp*0.8 + 2.0) * 0.5;
  }
  const act=aS/8, inh=iS/8, cat=cS/8;
  const bg = (Math.sin(sx*0.035+sy*0.02+t*0.7)+Math.sin(sx*0.025-sy*0.035+t*0.95)+Math.sin(sx*0.045+sy*0.04-t*0.5))/3;
  const micro = (Math.sin(sx*0.12+t*1.5)*Math.sin(sy*0.11-t*1.3)+Math.sin((sx-sy)*0.08+t*2.2))*0.5;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2), ang=Math.atan2(sy-cy,sx-cx);
  const spiral = (Math.sin(dist*0.045-ang*4-t*1.3)+Math.sin(dist*0.035+ang*5-t*1.0)+Math.sin(dist*0.06-ang*2-t*1.8))*0.33;
  const ring = Math.sin(dist*0.08-t*2.0)*Math.cos(ang*6+t*0.5)*0.3;
  const feed = Math.tanh((act - inh*0.65 + cat*0.25 + bg*0.25 + spiral + ring + micro*0.15)*2.0);
  const cell = Math.tanh((Math.sin(sx*0.14)*Math.sin(sy*0.14)+Math.sin((sx+sy)*0.09+t)*0.4+Math.sin(sx*0.07-t*0.5)*Math.cos(sy*0.09+t*0.3)*0.3)*1.3)*0.25;
  const laplacian = Math.sin(feed*3.5)*0.15;
  const blend = Math.tanh(feed*0.8 + cell*0.2 + laplacian)*0.85 + cell*0.15;
  const v = blend*0.5+0.5;
  const hueShift = Math.sin(t*0.2)*0.08;
  const pal = [
    [5,12,52],[10,45,85],[12,85,105],[18,135,130],[45,170,145],
    [120,190,120],[190,195,70],[220,165,55],[215,115,60],
    [185,70,70],[140,40,75],[85,25,65],[40,18,58],[5,12,52]
  ];
  const idx = (v+hueShift)*(pal.length-1);
  const ii = Math.max(0, Math.min(idx|0, pal.length-2));
  const f = idx - ii;
  const lum = 0.82+Math.sin(blend*Math.PI)*0.18;
  const edge = Math.abs(blend)>0.65 ? 1.0+Math.abs(blend)*0.2 : 1.0;
  const glow = Math.max(0, Math.abs(blend)-0.5)*0.4;
  return [
