    Math.min(255, ((pal[ii][1]+(pal[ii+1][1]-pal[ii][1])*f)*lum*edge + glow*25)|0),
    Math.min(255, ((pal[ii][2]+(pal[ii+1][2]-pal[ii][2])*f)*lum*edge + glow*50)|0)
  ];
}
